18: /// Known DJI `.DAT` blackbox sensor payload IDs per Section 6.4 of `SPECS.md`.
19: pub mod payload_ids {
20:     /// OSD / IMU Attitude, Angular Rates, Body Accelerations, and NED Velocities (`0x01` / `1`).
21:     pub const IMU_ATTITUDE: u16 = 0x01;
22:     /// GPS Raw binary sentences (`0x02` / `2`).
23:     pub const GPS_RAW: u16 = 0x02;
24:     /// Smart Battery diagnostics (`0x0A` / `10`).
25:     pub const SMART_BATTERY: u16 = 0x0A;
26:     /// Motor & ESC real-time rotor RPM and power stage diagnostics (`0x12` / `18`).
27:     pub const MOTOR_ESC: u16 = 0x12;
28:     /// Barometer & Compass atmospheric pressure and magnetometer field (`0x2A` / `42`).
29:     pub const BARO_COMPASS: u16 = 0x2A;
30: }
