32: /// Polymorphic representation of a parsed DJI `.DAT` blackbox payload.
33: #[derive(Clone, Copy, Debug, PartialEq)]
34: pub enum DatRecordPayload<'a> {
35:     /// Decoded IMU Attitude, Gyro rates, Accelerations, and Velocities (Payload 0x01).
36:     Imu(DatImuRecord),
37:     /// Decoded Motor & ESC diagnostics for up to 8 rotors (Payload 0x12).
38:     Motor(DatMotorRecord),
39:     /// Decoded Smart Battery diagnostics (Payload 0x0A).
40:     Battery(DatBatteryRecord),
41:     /// Raw unparsed payload bytes for extended or unknown sensor payload IDs.
42:     Unknown {
43:         /// Sensor payload identifier.
44:         payload_id: u16,
45:         /// Raw borrowed payload bytes.
46:         raw: &'a [u8],
47:     },
48: }
49: 
50: /// Parses a raw `.DAT` payload slice based on its `payload_id`.
51: pub fn parse_dat_payload(payload_id: u16, payload: &[u8]) -> Result<DatRecordPayload<'_>> {
52:     match payload_id {
53:         payload_ids::IMU_ATTITUDE => DatImuRecord::parse(payload).map(DatRecordPayload::Imu),
54:         payload_ids::MOTOR_ESC => DatMotorRecord::parse(payload).map(DatRecordPayload::Motor),
55:         payload_ids::SMART_BATTERY => DatBatteryRecord::parse(payload).map(DatRecordPayload::Battery),
56:         _ => Ok(DatRecordPayload::Unknown {
57:             payload_id,
58:             raw: payload,
59:         }),
60:     }
61: }
